package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * The sheet's figures as the screen shows them: each person's claimed and due-total, and the
 * sheet's claimed-total and due-total. A change takes a {@link #snapshot} before it and passes it
 * to {@link #recordChanges} after its own audit lines, which then records a ROLLUP line for each
 * person whose figures moved (people in the order they were added; a person new to the sheet
 * counts as moved) and a TOTALS line when the sheet's totals moved.
 */
@Service
public class RollupService {

    /** A person's figures: claimed, and due-total (null: n/a). */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal) {
        boolean sameAs(Figures other) {
            return other != null && claimed.compareTo(other.claimed) == 0
                    && Objects.equals(text(dueTotal), text(other.dueTotal));
        }
    }

    /** The sheet's figures at one moment: each person's, by person id in the order they were added. */
    public record Snapshot(Map<Long, Figures> people) {
        BigDecimal claimedTotal() {
            return people.values().stream().map(Figures::claimed).reduce(zero(), BigDecimal::add);
        }

        /** Everyone's due-total added up, skipping n/a. */
        BigDecimal dueTotal() {
            return people.values().stream().map(Figures::dueTotal).filter(Objects::nonNull)
                    .reduce(zero(), BigDecimal::add);
        }
    }

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's figures now, as the store (and this transaction) holds them. */
    public Snapshot snapshot(String sheetId) {
        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElseGet(LocalDate::now);
        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAsc(sheetId);
        List<Person> sheetPeople = people.findBySheetIdOrderByIdAsc(sheetId);
        Set<Long> held = heldIds(sheetPeople);
        Map<Long, List<Claim>> counted = new LinkedHashMap<>();
        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            if (counts(c, held)) {
                counted.computeIfAbsent(c.getPersonId(), id -> new ArrayList<>()).add(c);
            }
        }
        Map<Long, Figures> out = new LinkedHashMap<>();
        for (Person p : sheetPeople) {
            List<Rate> theirRates = sheetRates.stream().filter(r -> r.getGrade().equals(p.getGrade())).toList();
            List<Claim> theirs = counted.getOrDefault(p.getId(), List.of());
            BigDecimal claimed = theirs.stream().map(Claim::getAmount).reduce(zero(), BigDecimal::add);
            out.put(p.getId(), new Figures(p.getName(), claimed, dueTotalOf(theirs, theirRates, today)));
        }
        return new Snapshot(out);
    }

    /** The due-total of the period from {@code from} to {@code to}, inclusive: the dues (n/a ones
     *  skipped) its OPEN and SETTLED claims dated inside it show now (a held person's OPEN ones left out). */
    public BigDecimal dueTotalBetween(String sheetId, LocalDate from, LocalDate to) {
        List<Rate> sheetRates = rates.findBySheetIdOrderByGradeAsc(sheetId);
        List<Person> sheetPeople = people.findBySheetIdOrderByIdAsc(sheetId);
        Set<Long> held = heldIds(sheetPeople);
        Map<Long, List<Rate>> ratesByPerson = new LinkedHashMap<>();
        for (Person p : sheetPeople) {
            ratesByPerson.put(p.getId(), sheetRates.stream().filter(r -> r.getGrade().equals(p.getGrade())).toList());
        }
        return claims.findBySheetIdOrderByIdDesc(sheetId).stream()
                .filter(c -> counts(c, held))
                .filter(c -> !c.getDate().isBefore(from) && !c.getDate().isAfter(to))
                .map(c -> shownDueOf(c, ratesByPerson.getOrDefault(c.getPersonId(), List.of())))
                .filter(Objects::nonNull)
                .reduce(zero(), BigDecimal::add);
    }

    /** Record, once the transaction commits, a ROLLUP line for each person whose figures moved
     *  since {@code before}, then a TOTALS line when the sheet's totals moved. */
    public void recordChanges(String sheetId, String user, Snapshot before) {
        Snapshot after = snapshot(sheetId);
        after.people().forEach((id, now) -> {
            if (!now.sameAs(before.people().get(id))) {
                audit.recordOnCommit("ROLLUP sheet=" + sheetId + " by=" + user + " person=" + now.name()
                        + " claimed=" + text(now.claimed()) + " due-total=" + text(now.dueTotal()));
            }
        });
        if (after.claimedTotal().compareTo(before.claimedTotal()) != 0
                || after.dueTotal().compareTo(before.dueTotal()) != 0) {
            audit.recordOnCommit("TOTALS sheet=" + sheetId + " by=" + user + " claimed-total="
                    + text(after.claimedTotal()) + " due-total=" + text(after.dueTotal()));
        }
    }

    /** Whether a claim counts toward claimed and due totals: only OPEN and SETTLED ones do, and
     *  of a held person (by id in {@code held}) only SETTLED ones. */
    private static boolean counts(Claim c, Set<Long> held) {
        return c.getStatus() == ClaimStatus.SETTLED
                || (c.getStatus() == ClaimStatus.OPEN && !held.contains(c.getPersonId()));
    }

    private static Set<Long> heldIds(List<Person> sheetPeople) {
        return sheetPeople.stream().filter(Person::isHeld).map(Person::getId).collect(Collectors.toSet());
    }

    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
     *  null (n/a) when their grade has no rate in force on the sheet's today, unless a claim keeps
     *  a fixed or bound due. */
    private static BigDecimal dueTotalOf(List<Claim> counted, List<Rate> theirRates, LocalDate today) {
        boolean kept = counted.stream()
                .anyMatch(c -> c.getSettledDue() != null || (c.isStated() && c.getStatedDue() != null));
        if (inForce(theirRates, today).isEmpty() && !kept) {
            return null;
        }
        return counted.stream()
                .map(c -> shownDueOf(c, theirRates))
                .filter(Objects::nonNull)
                .reduce(zero(), BigDecimal::add);
    }

    /** The due a claim shows: the due fixed when it was settled, else the one a statement bound it
     *  to (null: n/a), else its amount times the rate in force on its date, rounded half to even. */
    private static BigDecimal shownDueOf(Claim c, List<Rate> theirRates) {
        if (c.getSettledDue() != null) {
            return c.getSettledDue();
        }
        if (c.isStated()) {
            return c.getStatedDue();
        }
        return inForce(theirRates, c.getDate())
                .map(r -> c.getAmount().multiply(r.getPct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
                .orElse(null);
    }

    private static Optional<Rate> inForce(List<Rate> theirRates, LocalDate on) {
        return theirRates.stream()
                .filter(r -> r.appliesOn(on))
                .max(Comparator.comparing(Rate::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())));
    }

    private static BigDecimal zero() {
        return BigDecimal.ZERO.setScale(2);
    }

    /** A figure as the screen shows it: two decimals, or n/a. */
    private static String text(BigDecimal value) {
        return value == null ? "n/a" : value.setScale(2).toPlainString();
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.period.PeriodService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonStatement;
import net.officefloor.hq.app.person.PersonStatementRepository;
import net.officefloor.hq.app.person.StatementSummary;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class ClaimService {

    private final ClaimRepository claims;
    private final PersonRepository people;
    private final PersonStatementRepository statements;
    private final RateRepository rates;
    private final SheetService sheets;
    private final RollupService rollup;
    private final PeriodService periods;
    private final SettingsService settings;
    private final Audit audit;

    /** A statement just taken: the person, their statement summary now, and their claims, newest first. */
    public record Statement(Person person, StatementSummary summary, List<Claim> claims) {
    }

    public ClaimService(ClaimRepository claims, PersonRepository people, PersonStatementRepository statements,
            RateRepository rates, SheetService sheets, RollupService rollup, PeriodService periods, SettingsService settings, Audit audit) {
        this.claims = claims;
        this.people = people;
        this.statements = statements;
        this.rates = rates;
        this.sheets = sheets;
        this.rollup = rollup;
        this.periods = periods;
        this.settings = settings;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByIdDesc(sheetId);
    }

    /** Add a claim for a person on the sheet; a missing date takes the sheet's today. Refused
     *  (423) when the date is in a closed period, and (422) when it is after the person's
     *  retirement date. */
    @Transactional
    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note) {
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseIfClosed(sheetId, on);
        refuseIfRetired(person, on);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Claim claim = claims.saveAndFlush(new Claim(sheetId, personId, amount, on, noteOf(note)));
        record("CLAIM_ADDED", user, person, claim);
        rollup.recordChanges(sheetId, user, before);
        return claim;
    }

    /** Change a DRAFT claim's amount, date and note; a missing date takes the sheet's today.
     *  Refused (409) once the claim is no longer a DRAFT (an open claim is voided and a new one
     *  added instead), and (423) when its old or new date is in a closed period, and (422) when the new
     *  date is after the person's retirement date. */
    @Transactional
    public Claim update(String sheetId, String user, long id, BigDecimal amount, LocalDate date, String note) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        LocalDate on = date != null ? date : sheets.today(sheetId);
        refuseIfClosed(sheetId, claim.getDate());
        if (claim.getStatus() != ClaimStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot be edited");
        }
        refuseIfClosed(sheetId, on);
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        refuseIfRetired(person, on);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        claim.setAmount(amount);
        claim.setDate(on);
        claim.setNote(noteOf(note));
        claims.flush();
        record("CLAIM_EDITED", user, person, claim);
        rollup.recordChanges(sheetId, user, before);
        return claim;
    }

    /** Move a claim to a new status; a move its status does not allow is refused (409), as is
     *  settling by the user who opened the claim (403), settling by a clerk a claim
     *  whose due is above the sheet's clerk limit (403), and any move of a claim dated in a closed
     *  period (423). */
    @Transactional
    public Claim changeStatus(String sheetId, String user, long id, ClaimStatus to) {
        Claim claim = claims.findForUpdate(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim"));
        refuseIfClosed(sheetId, claim.getDate());
        if (!claim.getStatus().canMoveTo(to)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "A " + claim.getStatus() + " claim cannot become " + to);
        }
        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "The user who opened a claim cannot settle it");
        }
        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        // a claim bound by a statement settles at its bound figure
        BigDecimal settling = to == ClaimStatus.SETTLED
                ? (claim.isStated() ? claim.getStatedDue() : dueOf(claim, person))
                : null;
        if (to == ClaimStatus.SETTLED && !settings.maySettle(sheetId, user, settling)) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
                    "A clerk cannot settle a claim whose due is above the clerk limit");
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        // a voided claim keeps its number (never reused), and the VOIDED record carries it
        Integer number = claim.getNumber();
        claim.setStatus(to);
        if (to == ClaimStatus.OPEN) {
            number = sheets.nextClaimNumber(sheetId);
            claim.setNumber(number);
            claim.setOpenedBy(user);
        } else if (to == ClaimStatus.SETTLED) {
            claim.setSettledDue(settling);
        }
        claims.flush();
        String event = switch (to) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> throw new IllegalArgumentException("A claim cannot return to DRAFT");
        };
        if (to == ClaimStatus.SETTLED) {
            BigDecimal due = claim.getSettledDue();
            record(event, user, person, claim, number, " due=" + (due == null ? "n/a" : due.toPlainString()));
        } else {
            record(event, user, person, claim, number);
        }
        rollup.recordChanges(sheetId, user, before);
        return claim;
    }

    /** Take a statement of a person: record their due-total now, and bind each of their claims
     *  that counts (OPEN or SETTLED) to the due it shows now; the others are left unbound. */
    @Transactional
    public Statement statement(String sheetId, String user, long personId) {
        Person person = people.findForUpdate(personId, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person"));
        LocalDate today = sheets.today(sheetId);
        List<Claim> theirs = claims.findByPersonForUpdate(personId, sheetId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        List<Claim> counted = theirs.stream().filter(ClaimService::counts).toList();
        BigDecimal dueTotal = dueTotalOf(counted, person, today);
        for (Claim c : theirs) {
            if (counts(c)) {
                c.bind(shownDueOf(c, person));
            } else {
                c.unbind();
            }
        }
        claims.flush();
        statements.saveAndFlush(new PersonStatement(sheetId, personId, dueTotal, counted.size(), today, user));
        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + counted.size());
        rollup.recordChanges(sheetId, user, before);
        return new Statement(person, StatementSummary.of(statements.findByPersonIdOrderByIdAsc(personId)), theirs);
    }

    /** Refuse (423) a change to a claim dated in a closed period, holding the sheet locked until
     *  the transaction ends so a period cannot be closed meanwhile. */
    private void refuseIfClosed(String sheetId, LocalDate date) {
        sheets.lock(sheetId);
        periods.refuseIfClosed(sheetId, date);
    }

    /** Refuse (422) a claim dated after its person's retirement date. */
    private static void refuseIfRetired(Person person, LocalDate date) {
        if (person.retiredBefore(date)) {
            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
                    "The date is after the person's retirement date");
        }
    }

    /** Whether a claim counts toward claimed and due totals: only OPEN and SETTLED ones do. */
    private static boolean counts(Claim c) {
        return c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.SETTLED;
    }

    /** The due a claim shows: the due fixed when it was settled, else the one a statement bound it
     *  to (null: n/a), else its live due. */
    private BigDecimal shownDueOf(Claim claim, Person person) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        return claim.isStated() ? claim.getStatedDue() : dueOf(claim, person);
    }

    /** A person's due-total: the sum of the dues their counting claims show (n/a ones skipped);
     *  null (n/a) when their grade has no rate in force on the sheet's today, unless a claim keeps
     *  a fixed or bound due. */
    private BigDecimal dueTotalOf(List<Claim> counted, Person person, LocalDate today) {
        boolean kept = counted.stream()
                .anyMatch(c -> c.getSettledDue() != null || (c.isStated() && c.getStatedDue() != null));
        if (rates.findInForce(person.getSheetId(), person.getGrade(), today).isEmpty() && !kept) {
            return null;
        }
        return counted.stream()
                .map(c -> shownDueOf(c, person))
                .filter(d -> d != null)
                .reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** The claim's amount times its person's grade rate in force on the claim's date, divided by
     *  100, rounded half to even; null with no rate in force then. */
    private BigDecimal dueOf(Claim claim, Person person) {
        return rates.findInForce(claim.getSheetId(), person.getGrade(), claim.getDate())
                .map(Rate::getPct)
                .map(pct -> claim.getAmount().multiply(pct).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
                .orElse(null);
    }

    private void record(String event, String user, Person person, Claim claim) {
        record(event, user, person, claim, claim.getNumber());
    }

    /** Amounts are written as the screen shows them (two decimals), dates as yyyy-mm-dd. */
    private void record(String event, String user, Person person, Claim claim, Integer number) {
        record(event, user, person, claim, number, "");
    }

    private void record(String event, String user, Person person, Claim claim, Integer number, String extra) {
        audit.recordOnCommit(event + " sheet=" + claim.getSheetId() + " by=" + user
                + " person=" + person.getName() + " amount=" + claim.getAmount().setScale(2).toPlainString()
                + " date=" + claim.getDate() + (number != null ? " number=" + number : "") + extra);
    }

    private static String noteOf(String note) {
        return note == null ? "" : note.trim();
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet: everything else in the app is kept per sheet. */
@Entity
@Table(name = "sheet")
public class Sheet {

    @Id
    private String id;

    @Column(name = "created_by", nullable = false)
    private String createdBy;

    /** The sheet's "today": every date decision and default date on the sheet uses it. */
    @Column(name = "today", nullable = false)
    private LocalDate today;

    /** The last number given to a claim opened on the sheet; 0 before the first. */
    @Column(name = "last_claim_number", nullable = false)
    private int lastClaimNumber;

    /** A clerk settles a claim only when its due is at or below this; null when there is no limit. */
    @Column(name = "clerk_limit", precision = 15, scale = 2)
    private BigDecimal clerkLimit;

    protected Sheet() {
    }

    public Sheet(String id, String createdBy, LocalDate today) {
        this.id = id;
        this.createdBy = createdBy;
        this.today = today;
    }

    public String getId() {
        return id;
    }

    public String getCreatedBy() {
        return createdBy;
    }

    public LocalDate getToday() {
        return today;
    }

    public void setToday(LocalDate today) {
        this.today = today;
    }

    public BigDecimal getClerkLimit() {
        return clerkLimit;
    }

    public void setClerkLimit(BigDecimal clerkLimit) {
        this.clerkLimit = clerkLimit;
    }

    /** Take the sheet's next claim number. */
    public int nextClaimNumber() {
        return ++lastClaimNumber;
    }
}
